python3 -c '
import json
from lightlag_surface import Surface, PHYSICS

with open("/tmp/map1.json") as f:
    m = json.load(f)
surf = Surface(m["cell_m"], m["elevation_cm"], m["terrain"])

# 60x40 grid (each char = 2x2 cells = 10m x 10m)
grid = [["." for _ in range(60)] for _ in range(40)]
for cy in range(40):
    for cx in range(60):
        steep = False
        terr_counts = {}
        for dj in range(2):
            for di in range(2):
                i, j = cx*2 + di, cy*2 + dj
                if surf.cell_max_slope(i, j) > 0.30:
                    steep = True
                if surf.cell_max_slope(i, j) > 0.36:
                    grid[cy][cx] = "#"
        if grid[cy][cx] != "#":
            if steep:
                grid[cy][cx] = "^"
            else:
                c = surf.codes[cy*2][cx*2]
                grid[cy][cx] = {"b": ".", "r": ",", "s": "~", "k": ":"}[c]

bx, by = int(m["base"][0] / 10), int(m["base"][1] / 10)
grid[by][bx] = "B"
for t in m["targets"]:
    tx, ty = min(59, int(t["x"] / 10)), min(39, int(t["y"] / 10))
    if grid[ty][tx] != "B":
        grid[ty][tx] = str(int(t["value"]))

for row in reversed(grid):
    print("".join(row))
'

