# Replan tour periodically or when plan empty/stale or current goal already sampled
need_replan = (
    (exec_tick - self.last_plan_tick >= 20)
    or (self.current_plan and self.current_plan[0] in pending_sampled and exec_tick - self.last_plan_tick >= 8)
    or (not self.current_plan and len(pending_sampled) < len(self.targets))
)
# Don't waste time replanning in the very final return sprint
if exec_tick >= self.max_ticks - 12 and not self.current_plan:
    need_replan = False

if need_replan:
    slip = self.ekf.slip_dict()
    self.current_plan = self.planner.plan_tour(
        x, y, exec_tick, bat_exec_start, self.targets, pending_sampled,
        slip, self.eff_est, current_plan=self.current_plan
    )
    self.last_plan_tick = exec_tick

# Filter out already pending-sampled targets from head of plan
while self.current_plan and self.current_plan[0] in pending_sampled:
    self.current_plan.pop(0)

# Determine current goal: next target in tour, or base
if self.current_plan:
    goal_t = self.target_by_id[self.current_plan[0]]
    gx, gy = float(goal_t["x"]), float(goal_t["y"])
    dist_goal = math.hypot(gx - x, gy - y)

    # Sampling condition!
    dl = goal_t["deadline_tick"]
    pos_std = math.sqrt(max(0.0, self.ekf.P[0][0] + self.ekf.P[1][1]))
    safe_sample_r = max(1.05, min(1.35, self.target_radius - 1.8 * pos_std - 0.35))
    if dist_goal <= safe_sample_r or (dl is not None and exec_tick == dl and dist_goal <= self.target_radius - 0.15):
        if bat_exec_start >= self.sample_cost + 1.0:
            return {"action": "sample"}

    goal_is_target = True
else:
    gx, gy = self.base
    dist_goal = math.hypot(gx - x, gy - y)
    if dist_goal <= max(1.5, self.base_radius - 1.8):
        return {"action": "wait"}
    goal_is_target = False

# Compute path / lookahead waypoint (prefer Dijkstra route unless close & safe)
if dist_goal <= 18.0 and self.router.line_safe(x, y, gx, gy):
    wp_x, wp_y = gx, gy
    is_final = True
else:
    if (
        self.cached_path_goal != (gx, gy)
        or not self.cached_path
        or math.hypot(self.cached_path[0][0] - x, self.cached_path[0][1] - y) > 15.0
    ):
        self.cached_path = self.router.get_path(x, y, gx, gy)
        self.cached_path_goal = (gx, gy)

    while len(self.cached_path) > 1 and math.hypot(self.cached_path[0][0] - x, self.cached_path[0][1] - y) < 4.5:
        self.cached_path.pop(0)

    wp_x, wp_y = self.cached_path[0]
    is_final = (len(self.cached_path) == 1)
    for idx in range(min(len(self.cached_path) - 1, 4), 0, -1):
        px, py = self.cached_path[idx]
        if self.router.line_safe(x, y, px, py):
            wp_x, wp_y = px, py
            is_final = (idx == len(self.cached_path) - 1)
            break

